```rust
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Phase {
    Idle,
    Active { name: String, advances: u64 },
    Completed { name: String, advances: u64 },
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ApplyError {
    Malformed { command_index: usize },
    InvalidTransition { command_index: usize },
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Workflow {
    phase: Phase,
}

impl Workflow {
    pub fn new() -> Self {
        Self { phase: Phase::Idle }
    }

    pub fn phase(&self) -> &Phase {
        &self.phase
    }

    pub fn apply_script(&mut self, script: &str) -> Result<(), ApplyError> {
        for (command_index, line) in script.lines().enumerate() {
            apply_line(&mut self.phase, line, command_index)?;
        }
        Ok(())
    }
}

fn apply_line(phase: &mut Phase, line: &str, command_index: usize) -> Result<(), ApplyError> {
    let fields: Vec<&str> = line.split_whitespace().collect();
    match fields.as_slice() {
        ["start", name] => match phase {
            Phase::Idle => {
                *phase = Phase::Active {
                    name: (*name).to_owned(),
                    advances: 0,
                };
                Ok(())
            }
            _ => Err(ApplyError::InvalidTransition { command_index }),
        },
        ["advance"] => match phase {
            Phase::Active { advances, .. } => {
                *advances += 1;
                Ok(())
            }
            _ => Err(ApplyError::InvalidTransition { command_index }),
        },
        ["finish"] => match phase {
            Phase::Active { name, advances } => {
                *phase = Phase::Completed {
                    name: name.clone(),
                    advances: *advances,
                };
                Ok(())
            }
            _ => Err(ApplyError::InvalidTransition { command_index }),
        },
        ["start", ..] | ["advance", ..] | ["finish", ..] | [] => {
            Err(ApplyError::Malformed { command_index })
        }
        _ => Err(ApplyError::Malformed { command_index }),
    }
}
```

